import {
  createLocalProviderPlugin2
} from "./repository-cache-09390rf8.js";

// src/plugin/provider/vllm.ts
import { Effect, Schema } from "effect";
var providerID = "vllm";
var RemoteModel = Schema.Struct({
  id: Schema.String,
  owned_by: Schema.String,
  max_model_len: Schema.NullOr(Schema.Int)
});
var Response = Schema.Struct({ data: Schema.Array(RemoteModel) });
var make5 = createLocalProviderPlugin2({
  id: "opencode.provider.vllm",
  providerID,
  name: "vLLM",
  origin: "http://127.0.0.1:8000",
  discover: (client) => Effect.gen(function* () {
    yield* client.get("/health");
    const response = yield* client.getJson("/v1/models", Response);
    return response.data.filter((model) => model.owned_by === providerID && model.id.length > 0).toSorted((a, b) => a.id.localeCompare(b.id));
  }),
  model: (item) => ({
    id: item.id,
    context: item.max_model_len
  })
});
var VLLMPlugin2 = make5();

